  /**
   * Identifies the item in `openSubNav` and is its React key, but isn't rendered to the DOM.
   */
  itemID: string
  /**
   * The visible text and accessible name of the item.
   */
  label: string
  /**
   * The URL of the page, ignored for items with a `subNav`.
   */
